// Spacer, AS GRAPH SOURCE (#3680, epic #3604) — a structural shared/ui layout primitive authored as DATA.
// `provides: "@/shared/ui/layout/Spacer"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). Transcribed verbatim; deps stay registered code.
// Spacer — flexible or fixed empty space inside a Row/Stack (#2056). Replaces the ~40 hand-rolled
// `<div style={{ flex: 1 }} />` fillers that push trailing items to the far end of a row.
//
//   <Row>  <h3>Title</h3>  <Spacer/>  <Button/>  </Row>   → button pinned right
//   <Row>  a  <Spacer size="md"/>  b  </Row>              → a fixed 12px gap between a and b
//
// A fixed spacer (`size`) reserves a rigid box along the parent's main axis; the default
// (sizeless) spacer greedily absorbs the remaining space.

import type { CSSProperties } from "react";
import { space, type Space } from "@/shared/ui/layout/space";

export interface SpacerProps {
  /** A rigid spacer of this size (scale rung or raw px). Omit for a flexible (`flex:1`) spacer. */
  size?: Space;
  style?: CSSProperties;
}

export function Spacer({ size, style }: SpacerProps) {
  if (size != null) {
    const n = space(size);
    // `flex: 0 0 <n>` sizes it along the parent's main axis regardless of row/column direction.
    return <div aria-hidden style={{ flex: `0 0 ${n}px`, ...style }} />;
  }
  return <div aria-hidden style={{ flex: 1, ...style }} />;
}

tests.src:
import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import { Spacer } from "./Spacer";

describe("Spacer", () => {
  it("is a greedy flex:1 filler by default", () => {
    const { container } = render(<Spacer />);
    const el = container.firstChild as HTMLElement;
    // jsdom's cssstyle serializer expands the `flex: 1` shorthand to its longhand equivalent.
    expect(el.style.flex).toBe("1 1 0%");
    expect(el.getAttribute("aria-hidden")).toBe("true");
  });

  it("becomes a rigid box sized along the main axis when given a size", () => {
    const { container } = render(<Spacer size="md" />);
    const el = container.firstChild as HTMLElement;
    expect(el.style.flex).toBe("0 0 12px");
  });

  it("accepts a raw px size and a style override", () => {
    const { container } = render(<Spacer size={20} style={{ opacity: 0 }} />);
    const el = container.firstChild as HTMLElement;
    expect(el.style.flex).toBe("0 0 20px");
    expect(el.style.opacity).toBe("0");
  });
});

// A retired module must still resolve — the regression that took the whole app down.
//
// `Spacer.tsx` was deleted once its record superseded it, which made the app depend on the generated
// `.bsc-records/` tree. Generation was wired into the `typecheck` / `test` / `build` npm scripts, so every
// gate command regenerated the tree as its FIRST step and no gate could ever observe the tree missing.
// `npm run dev` was not wired, so the dev server booted with the module unresolvable and died on
// `Failed to fetch dynamically imported module: /src/app/runtime/appModules.ts`.
//
// Generation now lives in the vite plugin's `buildStart`, which fires for serve and build alike — and for
// vitest, which is why this test is meaningful rather than circular: it exercises the SAME plugin path the
// dev server uses, not the npm script.
import { describe, it, expect } from "vitest";
import { Spacer } from "@/shared/ui/layout/Spacer";

describe("retired modules resolve through the record fallback", () => {
  it("imports a module whose file was deleted, from its packaged seed", () => {
    // If the fallback is broken this file fails to COLLECT — the import above throws before any assertion
    // runs — which is exactly the shape of the dev-server failure.
    expect(typeof Spacer).toBe("function");
  });
});
